PRAGMA foreign_keys = ON;
CREATE TABLE players (player_id TEXT PRIMARY KEY, display_name TEXT NOT NULL UNIQUE, core_player INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, notes TEXT);
CREATE TABLE player_aliases (alias_id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, alias TEXT NOT NULL, normalized_alias TEXT NOT NULL UNIQUE, FOREIGN KEY(player_id) REFERENCES players(player_id) ON DELETE CASCADE);
CREATE TABLE tournaments (tournament_id TEXT PRIMARY KEY, tournament_number INTEGER NOT NULL UNIQUE, tournament_date TEXT NOT NULL, winner_id TEXT NOT NULL, challonge_url TEXT, bracket_source TEXT NOT NULL DEFAULT 'unknown', match_data_available INTEGER NOT NULL DEFAULT 0, notes TEXT, FOREIGN KEY(winner_id) REFERENCES players(player_id));
CREATE TABLE tournament_participants (tournament_id TEXT NOT NULL, player_id TEXT NOT NULL, placement INTEGER, seed INTEGER, PRIMARY KEY(tournament_id, player_id), FOREIGN KEY(tournament_id) REFERENCES tournaments(tournament_id) ON DELETE CASCADE, FOREIGN KEY(player_id) REFERENCES players(player_id) ON DELETE CASCADE);
CREATE TABLE matches (match_id TEXT PRIMARY KEY, tournament_id TEXT NOT NULL, round_label TEXT, bracket_side TEXT, player_1_id TEXT NOT NULL, player_2_id TEXT NOT NULL, winner_id TEXT, player_1_score INTEGER, player_2_score INTEGER, score_known INTEGER NOT NULL DEFAULT 0, walkover INTEGER NOT NULL DEFAULT 0, source TEXT NOT NULL DEFAULT 'challonge', FOREIGN KEY(tournament_id) REFERENCES tournaments(tournament_id) ON DELETE CASCADE, FOREIGN KEY(player_1_id) REFERENCES players(player_id), FOREIGN KEY(player_2_id) REFERENCES players(player_id), FOREIGN KEY(winner_id) REFERENCES players(player_id));
CREATE TABLE rating_history (rating_id INTEGER PRIMARY KEY AUTOINCREMENT, player_id TEXT NOT NULL, tournament_id TEXT NOT NULL, match_id TEXT, rating_before REAL NOT NULL, rating_after REAL NOT NULL, rating_system TEXT NOT NULL DEFAULT 'elo', FOREIGN KEY(player_id) REFERENCES players(player_id), FOREIGN KEY(tournament_id) REFERENCES tournaments(tournament_id), FOREIGN KEY(match_id) REFERENCES matches(match_id));
